// -----------------------------------------------------------------------------
// g_readJsonFile
//
// Reads a JSON file and returns the parsed JavaScript object.
//
// Returns:
//   object - Parsed JSON object
//   null   - Failure
// -----------------------------------------------------------------------------

function g_readJsonFile(FQN) {
    try {

        const json = fs.readFileSync(FQN, "utf8");

        return JSON.parse(json);

    } catch (err) {

        node.error(
            `g_readJsonFile(): Unable to read '${FQN}': ${err.message}`
        );

        return null;
    }
}

